// Referencia o node Webhook direto
const webhookData = $('WebhookEvo').first().json.body.data.key;

const remoteJid = webhookData.remoteJid || '';
const remoteJidAlt = webhookData.remoteJidAlt || '';

console.log('remoteJid:', remoteJid);
console.log('remoteJidAlt:', remoteJidAlt);

// Função para validar e limpar o JID
function getValidJid(jid) {
  if (!jid || typeof jid !== 'string') return null;

  // Ignora @lid automaticamente
  if (jid.includes('@lid')) return null;

  // Regex para formato correto: remove :45 e outros lixos
  const match = jid.match(/^(\d+)(?::\d+)?(@s\.whatsapp\.net)$/);

  if (match) {
    return match[1] + match[2];
  }

  return null;
}

// Testa ambos
const validJid1 = getValidJid(remoteJid);
const validJid2 = getValidJid(remoteJidAlt);

// Prioriza o primeiro válido
let cleanJid = validJid1 || validJid2;

// Fallback: extrai só números se nenhum for válido
if (!cleanJid && (remoteJid || remoteJidAlt)) {
  // Só usa fallback em JIDs que NÃO sejam @lid
  const fallback = [remoteJid, remoteJidAlt]
    .find(j => j && !j.includes('@lid'));

  if (fallback) {
    const numbers = fallback.replace(/\D/g, '');
    if (numbers.length >= 10) {
      cleanJid = `${numbers}@s.whatsapp.net`;
    }
  }
}


return {
  remoteJid: cleanJid,
  original_remoteJid: remoteJid,
  original_remoteJidAlt: remoteJidAlt,
  is_valid: !!cleanJid,
  source: validJid1 ? 'remoteJid' : validJid2 ? 'remoteJidAlt' : 'fallback' // 👈
};

// Obtém os dados dos nodes anteriores
const message1Array = $('Get Memory 1').first().json.Message1;
const message2Array = $('Get Memory 2').first().json.Message2;

// Verifica se as variáveis são arrays válidas e combina os elementos em strings
const combinedText1 = Array.isArray(message1Array) ? message1Array.join(' ') : '';
const combinedText2 = Array.isArray(message2Array) ? message2Array.join(' ') : '';

// Retorna os valores combinados
return {
  combinedText1,
  combinedText2,
};

