const mensagem =
  $('Action Detector').first().json.categoryMessage ?? '';
const categorias =
  $('Get Categories').first().json.categories ?? [];
const merchantRule =
  $('Action Detector').first().json.createMerchantRule;

function normalizar(texto) {
  return String(texto)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // tira acentos
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ') // tira pontuação
    .replace(/\s+/g, ' ')
    .trim();
}

const mensagemNormalizada = ` ${normalizar(mensagem)} `;

const encontradas = categorias.filter(categoria => {
  const nome = normalizar(categoria.name);

  return mensagemNormalizada.includes(` ${nome} `);
});


// Achou exatamente uma categoria:
// não precisamos de IA.
if (encontradas.length === 1) {
  const categoria = encontradas[0];

  return [
    {
      json: {
        route: 'DIRECT',
        message: mensagem,

        action: 'CHANGE_CATEGORY',
        categoryId: categoria.id,
        categoryName: categoria.name,

        createMerchantRule: merchantRule
      }
    }
  ];
}


// Não achou nenhuma OU achou mais de uma:
// deixa a IA interpretar.
return [
  {
    json: {
      route: 'AI',
      message: mensagem,

      matchedCategories: encontradas,

      availableCategories: categorias.map(categoria => ({
        id: categoria.id,
        name: categoria.name,
        type: categoria.category_type
      }))
    }
  }
];

const output = $input.first().json.output;

const categorias = $('Get Categories').first().json.categories;

const valido =
  output.action === 'UNKNOWN' ||
  categorias.some(c => c.id === output.categoryId);

if (!valido) {
  throw new Error('categoryId inválido retornado pela IA');
}

return $input.all();

const mensagemOriginal =
  $('Combine Text').first().json.combinedText2 ?? '';

function normalizar(texto) {
  return String(texto)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

let mensagem = normalizar(mensagemOriginal);


// -------------------------
// DETECTA MERCHANT RULE
// -------------------------

const gatilhosRegra = [
  'cria uma regra',
  'criar uma regra',
  'salva uma regra',
  'salvar uma regra',
  'da proxima vez',
  'toda vez',
  'cria regra',
  'criar regra',
  'salva regra',
  'salvar regra',
  'sempre',
];

const createMerchantRule = gatilhosRegra.some(gatilho =>
  mensagem.includes(gatilho)
);


// Remove o pedido de regra antes de interpretar
// o restante da mensagem.
for (const gatilho of gatilhosRegra) {
  mensagem = mensagem.replaceAll(gatilho, ' ');
}

mensagem = mensagem
  .replace(/\s+/g, ' ')
  .trim();


// -------------------------
// DETECTA CONFIRMAÇÃO
// -------------------------

const confirmacoes = new Set([
  'sim',
  's',
  'si',
  'ok',
  'pode',
  'uhum',
  'ta certo',
  'certo',
  'correto',
]);

const confirmou = confirmacoes.has(mensagem);


// -------------------------
// OUTPUT
// -------------------------

if (confirmou) {
  return [
    {
      json: {
        route: 'CONFIRM',

        message: mensagemOriginal,

        action: 'ACCEPT_SUGGESTION',

        createMerchantRule,
      }
    }
  ];
}


// Não é confirmação.
// Desce para Get Categories.
return [
  {
    json: {
      route: 'CATEGORY',

      message: mensagemOriginal,

      // texto sem "sempre", "cria regra" etc.
      // pro detector de categoria / IA.
      categoryMessage: mensagem,

      createMerchantRule,
    }
  }
];

